#include <iostream>
using namespace std;

const long long M = 998244353;

long long computePower(long long base, long long exponent) {
    long long result = 1;
    long long mod = M;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % mod;
        }
        base = (base * base) % mod;
        exponent >>= 1;
    }
    return result;
}

long long modularInverse(long long a, long long m) {
    return computePower(a, m - 2);
}

int main() {
    long long m, n, l, r;
    cin >> m >> n >> l >> r;

    long long totalCount = m * n;
    long long segmentLength = r - l + 1;

    long long powerResult = computePower(segmentLength, totalCount);
    if (totalCount % 2 == 1) {
        cout << powerResult << "\n";
    } else {
        if (segmentLength % 2 == 0)
            cout << (powerResult * modularInverse(2, M)) % M << "\n";
        else
            cout << (((powerResult + 1) % M) * modularInverse(2, M)) % M << "\n";
    }
    return 0;
}
